import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function parseThresholds(thresholdStrings) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return null;
  }

  const result = {};
  const validMetricIds = new Set(DEFAULT_METRICS.map((m) => typeof m === 'function' ? m.name : m.id).filter(Boolean));
  validMetricIds.add('exact_match');
  validMetricIds.add('toxicity');
  validMetricIds.add('length_variance');

  for (const thresholdStr of thresholdStrings) {
    const parts = thresholdStr.split('=');
    if (parts.length !== 2) {
      throw new Error(`Malformed threshold: "${thresholdStr}". Expected format: <metric>=<number>`);
    }

    const [metricId, minStr] = parts;
    const min = Number.parseFloat(minStr);

    if (Number.isNaN(min)) {
      throw new Error(`Malformed threshold: "${thresholdStr}". Minimum value must be a number.`);
    }

    if (min < 0 || min > 1) {
      throw new Error(`Malformed threshold: "${thresholdStr}". Minimum value must be between 0 and 1.`);
    }

    if (!validMetricIds.has(metricId)) {
      throw new Error(`Unknown metric: "${metricId}". Valid metrics are: ${Array.from(validMetricIds).sort().join(', ')}`);
    }

    result[metricId] = min;
  }

  return result;
}

export class ThresholdError extends Error {
  constructor(message, validMetrics) {
    super(message);
    this.name = 'ThresholdError';
    this.validMetrics = validMetrics;
  }
}

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds) {
    const thresholdResults = [];
    let allPassed = true;

    for (const [metricId, min] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const passed = metric && typeof metric.score === 'number' && metric.score >= min;
      thresholdResults.push({
        metric: metricId,
        min,
        score: metric?.score ?? null,
        passed
      });
      if (!passed) {
        allPassed = false;
      }
    }

    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric,
  parseThresholds,
  ThresholdError
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric,
  parseThresholds,
  ThresholdError
};

