import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('report with thresholds shows passed=true when all metrics exceed minimums', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5, toxicity: 0.9 }
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toBeDefined();
    expect(report.thresholds).toHaveLength(2);
    const exactMatch = report.thresholds.find((t) => t.metric === 'exact_match');
    expect(exactMatch.passed).toBe(true);
    expect(exactMatch.score).toBe(1);
    expect(exactMatch.min).toBe(0.5);
  });

  it('report with thresholds shows passed=false when any metric is below minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.99, toxicity: 0.5 }
    });
    expect(report.passed).toBe(false);
    const exactMatch = report.thresholds.find((t) => t.metric === 'exact_match');
    expect(exactMatch.passed).toBe(false);
  });

  it('report with thresholds fails metric if score is null', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });
    expect(report.passed).toBe(false);
    const exactMatch = report.thresholds.find((t) => t.metric === 'exact_match');
    expect(exactMatch.passed).toBe(false);
    expect(exactMatch.score).toBeNull();
  });

  it('markdown report includes thresholds section when thresholds are provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.5 }
    });

    const dir = createTempDir();
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    const content = fs.readFileSync(markdownPath, 'utf8');
    expect(content).toContain('## Thresholds');
    expect(content).toContain('exact_match');
    expect(content).toContain('PASS');
  });

  it('markdown report shows FAIL for failed thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.99 }
    });

    const dir = createTempDir();
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    const content = fs.readFileSync(markdownPath, 'utf8');
    expect(content).toContain('## Thresholds');
    expect(content).toContain('FAIL');
  });

  it('json report includes passed and thresholds fields', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });

    const content = fs.readFileSync(jsonPath, 'utf8');
    const parsed = JSON.parse(content);
    expect(parsed.passed).toBe(true);
    expect(Array.isArray(parsed.thresholds)).toBe(true);
    expect(parsed.thresholds[0]).toHaveProperty('metric');
    expect(parsed.thresholds[0]).toHaveProperty('min');
    expect(parsed.thresholds[0]).toHaveProperty('score');
    expect(parsed.thresholds[0]).toHaveProperty('passed');
  });

  it('report without thresholds does not include passed or thresholds fields', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });

    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });
});

