    expect(() => parseThresholds(['exact_match=abc'])).toThrow('Minimum value must be a number');
  });

  it('throws on minimum below 0', () => {
    expect(() => parseThresholds(['exact_match=-0.1'])).toThrow('between 0 and 1');
  });

  it('throws on minimum above 1', () => {
    expect(() => parseThresholds(['exact_match=1.1'])).toThrow('between 0 and 1');
  });

  it('throws on unknown metric', () => {
    expect(() => parseThresholds(['unknown_metric=0.5'])).toThrow('Unknown metric');
  });

  it('error message includes valid metric ids', () => {
    try {
      parseThresholds(['invalid=0.5']);
      expect.fail('Should have thrown');
    } catch (error) {
      expect(error.message).toContain('exact_match');
      expect(error.message).toContain('toxicity');
      expect(error.message).toContain('length_variance');
    }
  });

  it('accepts boundary values', () => {
    const result = parseThresholds(['exact_match=0', 'toxicity=1']);
    expect(result).toEqual({ exact_match: 0, toxicity: 1 });
  });
});

