      thresholds = (Eval.parseThresholds as unknown as (strs: string[]) => Record<string, number>)(options.threshold);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      log.error('Threshold validation failed.', { error: message });
      process.exit(2);
    }
  }

